import java.util.*;

public List<Character> simpleTextEditor(String[] ops) {
    StringBuilder s = new StringBuilder();
    Deque<String> history = new ArrayDeque<>();
    List<Character> out = new ArrayList<>();
    for (String op : ops) {
        if (op.charAt(0) == '1') {
            String w = op.substring(2);
            history.push(s.toString());
            s.append(w);
        } else if (op.charAt(0) == '2') {
            int k = Integer.parseInt(op.substring(2).trim());
            history.push(s.toString());
            s.delete(s.length() - k, s.length());
        } else if (op.charAt(0) == '3') {
            int k = Integer.parseInt(op.substring(2).trim());
            out.add(s.charAt(k - 1));
        } else {
            s = new StringBuilder(history.pop());
        }
    }
    return out;
}

