import java.util.*;

public List<Character> simpleTextEditor(String[] ops) {
    StringBuilder s = new StringBuilder();
    Deque<int[]> appendLog = new ArrayDeque<>();   // marker for append: {1, len}
    Deque<String> deleteLog = new ArrayDeque<>();   // removed suffixes
    Deque<Integer> typeLog = new ArrayDeque<>();    // 1 = append, 2 = delete
    List<Character> out = new ArrayList<>();
    for (String op : ops) {
        if (op.charAt(0) == '1') {
            String w = op.substring(2);
            s.append(w);
            appendLog.push(new int[]{w.length()});
            typeLog.push(1);
        } else if (op.charAt(0) == '2') {
            int k = Integer.parseInt(op.substring(2).trim());
            String removed = s.substring(s.length() - k);
            s.delete(s.length() - k, s.length());
            deleteLog.push(removed);
            typeLog.push(2);
        } else if (op.charAt(0) == '3') {
            int k = Integer.parseInt(op.substring(2).trim());
            out.add(s.charAt(k - 1));
        } else {
            int t = typeLog.pop();
            if (t == 1) {
                int len = appendLog.pop()[0];
                s.delete(s.length() - len, s.length());
            } else {
                String removed = deleteLog.pop();
                s.append(removed);
            }
        }
    }
    return out;
}

