def simple_text_editor(self, ops: list[str]) -> list[str]:
    s: list[str] = []
    history: list[tuple] = []  # ('A', length) or ('D', removed_chars)
    out: list[str] = []
    for op in ops:
        if op[0] == '1':
            w = op[2:]
            s.extend(w)
            history.append(('A', len(w)))
        elif op[0] == '2':
            k = int(op.split()[1])
            removed = s[len(s) - k:]
            del s[len(s) - k:]
            history.append(('D', removed))
        elif op[0] == '3':
            k = int(op.split()[1])
            out.append(s[k - 1])
        else:
            kind, payload = history.pop()
            if kind == 'A':
                del s[len(s) - payload:]
            else:
                s.extend(payload)
    return out

